package com.mohymods.kingdomsmp.equipment;
import com.mohymods.kingdomsmp.placement.PlacementProtection;
import com.mohymods.kingdomsmp.profession.*;
import com.mohymods.kingdomsmp.building.ConstructionService;
import net.minecraft.core.*;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.network.chat.Component;
import net.minecraft.server.level.*;
import net.minecraft.tags.*;
import net.minecraft.world.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.phys.*;
import net.neoforged.neoforge.event.tick.ServerTickEvent;
import java.util.*;
/** All removals use native successful player mining and normal loot; no fabricated drops or chunk tickets. */
public final class MasterToolService {
 public record Plan(ServerLevel level,ItemStack tool,Map<BlockPos,BlockState> cells,BlockPos root,String sapling) { }
 private record Work(Plan plan,ArrayDeque<BlockPos> remaining){ }
 private static final Map<ServerPlayer,Work> WORK=new WeakHashMap<>();
 private record SurveyBudget(long window,int used) { }
 private static final Map<net.minecraft.server.MinecraftServer,SurveyBudget> SURVEY=new WeakHashMap<>();
 private static final Set<ServerPlayer> MINING=Collections.newSetFromMap(new WeakHashMap<>());
 private MasterToolService() { }
 public static boolean permitted(ServerPlayer p,BlockPos pos){var l=p.serverLevel();return com.mohymods.kingdomsmp.kingdom.AlphaScope.destinationAvailable(com.mohymods.kingdomsmp.contribution.ContributionService.kingdom(p.server).attainedTier(),l.dimension().location().toString())&&p.getAbilities().mayBuild&&p.isAlive()&&!p.isCreative()&&!p.isSpectator()&&p.server.getPlayerList().getPlayer(p.getUUID())==p&&l.hasChunkAt(pos)&&l.getWorldBorder().isWithinBounds(pos)&&pos.getY()>=l.getMinBuildHeight()&&pos.getY()<l.getMaxBuildHeight()&&p.distanceToSqr(Vec3.atCenterOf(pos))<=1024&&PlacementProtection.check(l,p,pos,pos)==null&&TreeLifecycle.consent(l,p,pos)&&!ConstructionService.protectedAt(l,pos);}
 public static boolean ore(BlockState state){var id=BuiltInRegistries.BLOCK.getKey(state.getBlock());return state.is(net.neoforged.neoforge.common.Tags.Blocks.ORES)&&Set.of("minecraft","mekanism","aether","twilightforest").contains(id.getNamespace());}
 public static Plan capture(ServerPlayer p,BlockPos first){try{
  if(!p.getMainHandItem().is(MasterGearItems.item(MasterGear.AXE))&&!p.getMainHandItem().is(MasterGearItems.item(MasterGear.PICKAXE))||MINING.contains(p)||WORK.containsKey(p)||p.isShiftKeyDown()||!permitted(p,first))return null;var tool=p.getMainHandItem();var l=p.serverLevel();var rules=MasterGearRules.get(p.server);Map<BlockPos,BlockState> cells=new LinkedHashMap<>();BlockPos root=null;String sapling=null;
  if(tool.is(MasterGearItems.item(MasterGear.AXE))){TreeLifecycle.drain(p.server,128);var tree=MasterGrownTrees.footprint(l,first).orElseGet(()->TreeSavedData.get(p.server).evidence().footprint(l.dimension().location().toString(),first).orElse(null));if(tree==null||tree.positions().size()>rules.treeLimit())return null;root=tree.origin();sapling=tree.sapling();for(var at:tree.positions())cells.put(at,l.getBlockState(at));}
  else if(tool.is(MasterGearItems.item(MasterGear.PICKAXE))&&ore(l.getBlockState(first))){var state=l.getBlockState(first);var queue=new ArrayDeque<BlockPos>();var seen=new HashSet<BlockPos>();queue.add(first.immutable());while(!queue.isEmpty()&&cells.size()<rules.veinLimit()){var at=queue.removeFirst();if(!seen.add(at)||at.distManhattan(first)>16||!l.hasChunkAt(at)||!l.getBlockState(at).is(state.getBlock())||!permitted(p,at))continue;cells.put(at,l.getBlockState(at));for(var d:Direction.values())queue.add(at.relative(d));}}
  else return null;
  if(cells.isEmpty()||!cells.containsKey(first))return null;for(var at:cells.keySet())if(!permitted(p,at)||l.getBlockState(at).getDestroySpeed(l,at)<0||!tool.isCorrectToolForDrops(l.getBlockState(at)))return null;return new Plan(l,tool,Map.copyOf(cells),root,sapling);
 }catch(RuntimeException failure){return null;}}
 public static void completed(ServerPlayer p,BlockPos first,Plan plan,boolean success){if(plan==null||!success||!p.serverLevel().getBlockState(first).isAir())return;var cells=new ArrayDeque<>(plan.cells().keySet().stream().filter(at->!at.equals(first)).sorted(Comparator.comparingInt((BlockPos at)->at.getY()).reversed()).toList());WORK.put(p,new Work(plan,cells));}
 public static void tick(ServerTickEvent.Post event){try{MasterGrownTrees.drain(event.getServer());}catch(RuntimeException failure){com.mojang.logging.LogUtils.getLogger().warn("Optional Master tree queue unavailable; native growth/mining continue",failure);}int budget=128;for(var p:new ArrayList<>(WORK.keySet())){if(p.server!=event.getServer())continue;try{var work=WORK.get(p);if(!p.isAlive()||p.serverLevel()!=work.plan().level()||p.getMainHandItem()!=work.plan().tool()||p.server.getPlayerList().getPlayer(p.getUUID())!=p){WORK.remove(p);continue;}boolean stopped=false;for(int n=0;n<8&&budget-->0&&!work.remaining().isEmpty();n++){var at=work.remaining().removeFirst();if(!permitted(p,at)||!p.serverLevel().getBlockState(at).equals(work.plan().cells().get(at))){stopped=true;break;}MINING.add(p);try{if(!p.gameMode.destroyBlock(at)){stopped=true;break;}}finally{MINING.remove(p);}}
   if(stopped||work.remaining().isEmpty()){WORK.remove(p);if(!stopped)replant(p,work.plan());}if(budget<=0)break;}catch(RuntimeException failure){WORK.remove(p);p.sendSystemMessage(Component.literal("Master tool work stopped; no queued block is retried or duplicated."));}
 }}
 private static void replant(ServerPlayer p,Plan plan){if(plan.root()==null||plan.sapling()==null)return;var at=plan.root();var l=p.serverLevel();if(!permitted(p,at)||!l.getBlockState(at).isAir())return;var id=net.minecraft.resources.ResourceLocation.parse(plan.sapling());var item=BuiltInRegistries.ITEM.getOptional(id).orElse(null);if(!(item instanceof BlockItem))return;int old=p.getInventory().selected;for(int slot=0;slot<36;slot++)if(p.getInventory().getItem(slot).is(item)){var held=p.getMainHandItem();var seed=p.getInventory().getItem(slot);p.getInventory().setItem(old,seed);if(slot!=old)p.getInventory().setItem(slot,held);try{p.gameMode.useItemOn(p,l,p.getMainHandItem(),InteractionHand.MAIN_HAND,new BlockHitResult(at.below().getCenter().add(0,.5,0),Direction.UP,at.below(),false));}finally{var remainder=p.getInventory().getItem(old);p.getInventory().setItem(old,held);if(slot!=old)p.getInventory().setItem(slot,remainder);}break;}}
 public static void survey(ServerPlayer p){try{if(!p.getMainHandItem().is(MasterGearItems.item(MasterGear.PICKAXE)))return;var rules=MasterGearRules.get(p.server);long now=p.server.overworld().getGameTime();var persistent=p.getPersistentData().getCompound(net.minecraft.world.entity.player.Player.PERSISTED_NBT_TAG).copy();long next=persistent.getLong("KingdomMasterSurveyNext");if(now<next){p.displayClientMessage(Component.literal("Survey recharges in "+((next-now+19)/20)+" seconds."),true);return;}if(!permitted(p,p.blockPosition()))return;var budget=SURVEY.get(p.server);long window=now/20;if(budget!=null&&budget.window()==window&&budget.used()>=4){p.displayClientMessage(Component.literal("Survey network is busy; try again shortly."),true);return;}SURVEY.put(p.server,new SurveyBudget(window,budget!=null&&budget.window()==window?budget.used()+1:1));persistent.putLong("KingdomMasterSurveyNext",Math.addExact(now,rules.surveyCooldown()));p.getPersistentData().put(net.minecraft.world.entity.player.Player.PERSISTED_NBT_TAG,persistent);p.getCooldowns().addCooldown(MasterGearItems.item(MasterGear.PICKAXE),rules.surveyCooldown());Map<String,List<BlockPos>> found=new TreeMap<>();int radius=rules.surveyRadius();for(var pos:BlockPos.betweenClosed(p.blockPosition().offset(-radius,-radius,-radius),p.blockPosition().offset(radius,radius,radius))){if(!p.serverLevel().hasChunkAt(pos))continue;var state=p.serverLevel().getBlockState(pos);if(ore(state)&&permitted(p,pos)&&p.getMainHandItem().isCorrectToolForDrops(state))found.computeIfAbsent(BuiltInRegistries.BLOCK.getKey(state.getBlock()).toString(),k->new ArrayList<>()).add(pos.immutable());}if(found.isEmpty())p.sendSystemMessage(Component.literal("Prospector: no eligible ores in permitted loaded terrain within "+radius+" blocks."));else found.entrySet().stream().limit(8).forEach(e->{var near=e.getValue().stream().min(Comparator.comparingDouble(at->p.distanceToSqr(at.getCenter()))).orElseThrow();var d=near.subtract(p.blockPosition());p.sendSystemMessage(Component.literal(e.getKey()+": "+e.getValue().size()+" nearby; offset "+d.toShortString()+" (same dimension, loaded and permitted)."));});}catch(RuntimeException failure){p.sendSystemMessage(Component.literal("Survey unavailable; no resources or progress changed."));}}
}
